WITH lines AS (SELECT id, created_at, coupon_codes, attr_key, value FROM carts LATERAL VIEW EXPLODE(attributes) t AS attr_key, value), scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY created_at DESC, id, attr_key) AS event_seq, ROW_NUMBER() OVER (PARTITION BY attr_key ORDER BY created_at, id, attr_key) AS event_seq_2 FROM lines), valid AS (SELECT *, ARRAY_CONTAINS(coupon_codes, 'WELCOME5') AS is_welcome5 FROM scored WHERE attr_key IS NOT NULL AND event_seq_2 < 6) SELECT attr_key, PERCENTILE_APPROX(event_seq_2, 0.9) AS event_seq_2_p90, APPROX_PERCENTILE(event_seq, ARRAY(0.25, 0.5, 0.75)) AS event_seq_quartiles, MIN(created_at) AS started_at, MIN(event_seq_2) AS min_event_seq_2, COUNT(*) AS cnt FROM valid GROUP BY attr_key
